    fermer();
    source = mot; mot.setAttribute('aria-expanded', 'true');
    bulle = document.createElement('div');
    bulle.className = 'gl-bulle'; bulle.setAttribute('role', 'dialog'); bulle.setAttribute('aria-label', d[0]);
    var t = document.createElement('div'); t.className = 'gl-bulle-titre'; t.textContent = '📖 ' + d[0];
    var p = document.createElement('p'); p.textContent = d[1];
